'use client';

import React, { useState } from 'react';
import styles from './MenuSection.module.css';
import { usePublicMenus, MenuListParams } from '@/hooks/usePublicMenus';
import { usePublicCategories } from '@/hooks/usePublicCategories';
import PublicMenuCard from './PublicMenuCard';

export default function MenuSection() {
    const [selectedCategory, setSelectedCategory] = useState<number | null>(null);
    const { categories } = usePublicCategories();

    // 메뉴 목록 조회
    const params: MenuListParams = {
        categoryId: selectedCategory
    };
    const { menus, loading, error } = usePublicMenus(params);

    return (
        <section id="menu-section" className={styles.section}>
            <div className={styles.header}>
                <h2 className={styles.title}>Our Menu</h2>
                <p className={styles.subtitle}>Discover our selection of fresh and delicious items.</p>
            </div>

            {/* Category Tabs */}
            <div className={styles.tabs}>
                <button
                    className={`${styles.tab} ${selectedCategory === null ? styles.active : ''}`}
                    onClick={() => setSelectedCategory(null)}
                >
                    All
                </button>
                {categories.map((category) => (
                    <button
                        key={category.id}
                        className={`${styles.tab} ${selectedCategory === category.id ? styles.active : ''}`}
                        onClick={() => setSelectedCategory(category.id)}
                    >
                        {category.name}
                    </button>
                ))}
            </div>

            {/* Menu Grid */}
            {loading ? (
                <div className={styles.loading}>Loading menus...</div>
            ) : error ? (
                <div className={styles.error}>{error}</div>
            ) : menus.length === 0 ? (
                <div className={styles.empty}>No menus available for this category.</div>
            ) : (
                <div className={styles.grid}>
                    {menus.map((menu) => (
                        <div key={menu.id}>
                            <PublicMenuCard menu={menu} />
                        </div>
                    ))}
                </div>
            )}
        </section>
    );
}
